Shell(BASE=http://localhost:4000 TOKEN=$(cat /tmp/gktv-token.txt) AUTH="authorization: Bearer $TOKEN" J='content-type: application/json' echo "=== 11. create (future-dated, should stay hidden from public) ===" NEW=$(curl -sS -X POST "$BASE/api/admin/stories" -H "$AUTH" -H "$J" \ -d '{"slug":"smoke-test-dispatch","category":"Kashmir","title":"A smoke test dispatch","summary":"Temporary row.","author":"QA","image_key":"lead","featured":false,"display_order":99,"published_at":"2030-01-01T00:00:00.000Z"}') ID=$(echo "$NEW" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{console.log(JSON.parse(d).data.id)})") echo "created id: $ID" echo -n "public total (should still be 12): "; curl -sS "$BASE/api/stories" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>console.log(JSON.parse(d).meta.total))" echo -n "hidden slug via public (expect 404): "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/stories/smoke-test-dispatch" echo -n "admin total (should be 13): "; curl -sS "$BASE/api/admin/stories" -H "$AUTH" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>console.log(JSON.parse(d).meta.total))" echo "=== 12. duplicate slug (expect 409) ===" curl -sS -o /dev/null -w "%{http_code}
" -X POST "$BASE/api/admin/stories" -H "$AUTH" -H "$J" \ -d '{"slug":"smoke-test-dispatch","category":"Kashmir","title":"dup","summary":"dup","author":"QA","image_key":"lead"}' echo "=== 13. validation error (expect 422 + details) ===" curl -sS -X POST "$BASE/api/admin/stories" -H "$AUTH" -H "$J" -d '{"slug":"Bad Slug","title":""}'; echo echo "=== 14. update (partial: publish it now) ===" curl -sS -X PUT "$BASE/api/admin/stories/$ID" -H "$AUTH" -H "$J" \ -d '{"published_at":"2020-01-01T00:00:00.000Z","featured":true}' \ | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{const s=JSON.parse(d).data;console.log('featured:',s.featured,'| published_at:',s.published_at)})" echo -n "now visible publicly (expect 200): "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/stories/smoke-test-dispatch" echo "=== 15. 404s ===" echo -n "unknown slug: "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/stories/nope-nope" echo -n "unknown id: "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/admin/stories/11111111-1111-4111-8111-111111111111" -H "$AUTH" echo -n "bad id uuid: "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/admin/stories/not-a-uuid" -H "$AUTH" echo -n "unknown route:"; curl -sS -o /dev/null -w " %{http_code}
" "$BASE/api/does-not-exist" echo -n "bad token: "; curl -sS -o /dev/null -w "%{http_code}
" "$BASE/api/admin/stories" -H "authorization: Bearer nope.nope.nope" echo "=== 16. delete (expect 204 then 404) ===" echo -n "delete: "; curl -sS -o /dev/null -w "%{http_code}
" -X DELETE "$BASE/api/admin/stories/$ID" -H "$AUTH" echo -n "re-delete:"; curl -sS -o /dev/null -w " %{http_code}
" -X DELETE "$BASE/api/admin/stories/$ID" -H "$AUTH" echo -n "final public total (expect 12): "; curl -sS "$BASE/api/stories" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>console.log(JSON.parse(d).meta.total))" echo "=== 17. CORS preflight ===" curl -sS -o /dev/null -D - -X OPTIONS "$BASE/api/stories" -H "Origin: http://localhost:8080" -H "Access-Control-Request-Method: GET" 2>/dev/null | grep -i "access-control-allow-origin\|HTTP/")
